@Clue80:
	If ($Shashousw == 1) @Clue90;
	
	Say("独孤剑：男子汉大丈夫，岂能临阵退缩！", 5);
	Return;
	
@Clue90:
	Say("杨瑛：独孤大哥，我们先进去查看一番。",39);
	Return;

traps.trap02.txt:
//切换到map113五剑堂正厅

	If ($Clue == 80) @Clue80;
	If ($Clue == 90) @Clue90;
	If ($Clue == 110) @Clue110;
	
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map113_五剑堂正厅-1.map");
	LoadNpc("map113.npc");
	LoadObj("map113-1.obj");
	SetPlayerPos(25,50);
	SetPlayerDir(3);
	FadeIn();
	Return;

@Clue80:
	If ($shashousw == 1) @Clue85;
	
	Say("五色教杀手：不能放他进去！", 80);
	Return;
	
@Clue85:
	StopMusic();
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map113_五剑堂正厅-1.map");
	LoadNpc("map113.npc");
	LoadObj("map113-1.obj");
	SetPlayerPos(24,49);
	SetPlayerDir(3);
