	SetNpcActionFile("杨瑛",0, "mpc035_2.asf");
	SetNpcActionFile("杨瑛",1, "mpc035_2.asf");
	NpcSpecialAction("杨瑛", "mpc035_1.asf");
	Sleep(1500);
	SaveNpc();
	DelNpc("杨瑛");	//对存盘的处理
	AddNpc("npc008_中毒的杨瑛.ini", 26, 50, 3);
