	SetPlayerDir(7);
	Say("独孤剑：杨姑娘！", 6);
	
	PlayMusic("追缘.mp3");
	PlayerRunTo(25,50);
	SetPlayerDir(5);
	Sleep(500);
	Say("杨瑛：啊——不，不要靠近我，是，是……是剧毒！快……回城找索七取……取圣药……", 42);
	Say("独孤剑：我马上去取！杨姑娘，你要坚持住！", 9);
	SetNpcKind("杨瑛", 0); 
	Assign($Clue, 90);
	Memo("一进五剑堂口，杨瑛便中了机关，身中剧毒。独孤剑只得赶回城找索七取解药。");
	Return;
	
@Clue90:
	Say("独孤剑：还是尽快取到圣药罢……", 9);
	Return;

@Clue110:
	FadeOut();
	StopMusic();
	SaveNpc();
	SaveObj();
	LoadMap("map113_五剑堂正厅-1.map");
	LoadNpc("map113.npc");
	DelNpc("杨瑛");
	SaveNpc();
	LoadObj("map113-1.obj");
	ChangeMapColor(255,255,255);
	ChangeAsfColor(255,255,255);
	SetPlayerPos(25,50);
	SetPlayerDir(3);
	PlayMusic("黑影.mp3");
	FadeIn();
	Say("独孤剑：糟了！杨姑娘呢……", 6);
	Memo("独孤剑赶回五剑堂，遇到一群五色教杀手，心中暗叫不妙。进入五剑堂后，杨瑛果然不知去向。");
	Return;

traps.trap03.txt:
//和五剑堂守卫对话

	If ($Clue == 71) @Clue71;
	If ($Clue == 75) @Clue75;
	
	Say("庄园守卫：去去去，这里是方员外的山庄。");
	NpcGotoEx("杨瑛",18,52);
	PlayerGotoDir(7,2);
	Assign($Talkfangzhang, 1);
	SetMapTrap(03,"trap03.txt");
	Return;
	
@Clue71:
	Say("庄园守卫：去去去，这里是方员外的山庄。");
	PlayerGotoDir(7,2);
	Say("杨瑛：方员外山庄……", 39);
	Say("杨瑛：“方”——正正方方。独孤大哥，这“口”不正可以解作“方”吗！", 42);
	Say("独孤剑：不错，果然如此！", 6);
	Say("杨瑛：江湖传言，方勉就是五色教的教主，莫非这山庄便是五色教的总坛？", 39);
	Say("独孤剑：好！我们进去瞧瞧！", 1);
	Assign($Clue, 75);
	SetMapTrap(02,"trap02.txt");
	SetMapTrap(03,"trap03.txt");
	Memo("方氏山庄门外，杨瑛突然想到“口”可能指的就是“方”字。两人决定进去瞧瞧。");
	SaveMapTrap();

	Return;
	
@Clue75:
	Say("庄园守卫：去去去，这里是方员外的山庄。");
	Say("独孤剑：五彩闪华轮，圣色照乾坤——", 1);
	Say("庄园守卫：——摩尼教千岁，万世奉王灯。两位是哪一堂的？");
	Say("独孤剑：果然是五色教的巢穴！", 2);
	StopMusic();
	Say("庄园守卫：啊——不好！");

	PlayMusic("杀机.mp3");
	NpcGotoEx("庄丁1",14,44); //五色教守卫
	NpcGoto("庄丁2",15,39);
	DelNpc("庄丁1");
	DelNpc("庄丁2");
	
	Say("杨瑛：我们杀进去！", 39);
	Say("独孤剑：杨姑娘，小心！", 1);
	Say("杨瑛：嗯。", 39);
	SetMapTrap(03,"");
	SaveMapTrap();
	Assign($Clue,80);
	Return;
